/* Demand-first creation prototype. No generation or publication service is called. */
const videoFlow={phase:0,request:'',files:[],prompt:'',error:'',previewUrl:'',outputSample:false,metadata:null};
function vClearMedia(){if(videoFlow.previewUrl)URL.revokeObjectURL(videoFlow.previewUrl);videoFlow.previewUrl='';videoFlow.metadata=null;videoFlow.pendingOutput=null;videoFlow.mediaContext=null;}
function vChange(){DY.invalidate(dyState);dyState.asset=null;vClearMedia();videoFlow.outputSample=false;videoFlow.prompt='';}
function videoWorkspace(){if(tabName==='执行记录')return dyLogs();return `<div class="dy-work">${dyContext()}${dyIntro('sparkles','你说需求，我先把创作方案整理好','从一句话开始，补充、修改并确认后再生成。')}<div class="dy-flow">${['说需求','确认简报','预览成片','确认发布'].map((x,i)=>`<button class="${videoFlow.phase===i?'active':''}" ${i>videoFlow.phase?'disabled':''} onclick="videoFlow.phase=${i};render()"><span>${i+1}</span>${x}</button>`).join('')}</div>${videoFlow.error?`<div role="alert" class="video-error">${esc(videoFlow.error)}</div>`:''}${[vDemand,vBrief,vOutput,vPublish][videoFlow.phase]()}</div>`;}
function vDemand(){return `<div class="dy-card dy-demand"><div class="dy-kicker">和抖音员工说一说</div><h3>这次想给门店做一条什么视频？</h3><p>告诉我面向谁、想表达什么、有什么活动，以及你不想出现的内容。</p><label class="sr-only" for="vRequest">创作需求</label><textarea id="vRequest" maxlength="2000" oninput="videoFlow.request=this.value" placeholder="比如：帮滨江店做一条周末会员活动视频，30秒竖屏，给附近车主看。突出洗车服务，专业可信，不要夸张促销，不要出现明火。">${esc(videoFlow.request)}</textarea><div class="dy-suggestions">${['做一条30秒会员活动视频，专业可信，不要夸张促销','给今晚直播做一条15秒引流视频，不要虚构价格','展示油站环境和员工服务，清新明亮，不要危险操作'].map((s,i)=>`<button class="secondary" onclick="vExample(${i})">${['会员活动','直播预热','门店形象'][i]}</button>`).join('')}</div><div class="dy-row actions"><small>本地规则预填演示 · 不会发送需求或素材</small><button class="primary" onclick="vParseDemand()">${icon('sparkles')} 整理创作简报</button></div></div><div class="dy-card"><h3>你只需确认关键内容</h3><div class="dy-grid three"><div><strong>员工先整理</strong><p>目标、受众、规格与表达方式。</p></div><div><strong>你来补充</strong><p>活动条件、必须保留和不要出现的内容。</p></div><div><strong>确认再执行</strong><p>先确认简报，再核对成片和发布账号。</p></div></div></div>`;}
function vExample(i){videoFlow.request=['帮滨江店做一条30秒竖屏会员活动视频，给附近车主看，突出洗车服务，专业可信，不要夸张促销和明火。','为今晚油站直播做一条15秒竖屏预热视频，吸引附近车主，不要虚构价格和限量。','展示油站环境和员工服务，20秒竖屏，清新明亮，不要危险操作和夸大效果。'][i];render();}
function vParseDemand(){const request=videoFlow.request.trim();if(!request){videoFlow.error='先告诉员工你想做什么视频。';render();return;}vChange();dyState.brief=DY.prefill(request);videoFlow.phase=1;videoFlow.error='';DY.log(dyState,'根据客户需求预填创作简报（本地规则演示）');render();}
function vBriefField(key,label,multi=false,help=''){const value=dyState.brief[key];return `<div class="field ${multi?'wide':''}"><label for="v_${key}">${label}${help?'<small>'+help+'</small>':''}</label>${multi?`<textarea id="v_${key}" maxlength="2000" oninput="vEditBrief('${key}',this.value)">${esc(value)}</textarea>`:`<input id="v_${key}" maxlength="300" value="${esc(value)}" oninput="vEditBrief('${key}',this.value)">`}</div>`;}
function vBrief(){if(!dyState.brief){videoFlow.phase=0;return vDemand();}const b=dyState.brief;return `<div class="dy-card"><div class="dy-chat"><span class="dy-icon">${icon('sparkles')}</span><div><strong>我先按你的需求整理了一版</strong><p>${esc(b.request)}</p><small>主题、时长和“不要什么”优先取自原话；其余为建议值，请确认。价格和活动条件不自动编造。</small></div></div><div class="dy-form-grid">${vBriefField('goal','创作目标')}${vBriefField('audience','目标受众')}${vBriefField('theme','视频主题')}${vBriefField('style','视觉风格')}<div class="field"><label for="v_duration">时长</label><select id="v_duration" onchange="vEditBrief('duration',this.value)">${['15','20','30','45','60'].map(x=>`<option value="${x}" ${b.duration===x?'selected':''}>${x} 秒</option>`).join('')}</select></div><div class="field"><label for="v_ratio">画幅</label><select id="v_ratio" onchange="vEditBrief('ratio',this.value)">${['9:16','16:9','1:1'].map(x=>`<option ${b.ratio===x?'selected':''}>${x}</option>`).join('')}</select></div>${vBriefField('voice','配音 / 口播')}${vBriefField('subtitles','字幕')}${vBriefField('music','配乐方向')}${vBriefField('cta','结尾引导')}${vBriefField('must','必须保留什么',true)}${vBriefField('avoid','不要出现什么',true,'负向要求会跟随生成方案')}${vBriefField('notes','待补充 / 活动信息',true)}</div></div><div class="dy-card"><div class="dy-row"><h3>参考素材 <span class="dy-tag">${videoFlow.files.length} / 至少 3 个</span></h3><button class="link" onclick="loadVideoSample()">载入示例素材</button></div><p>补充门店外观、员工服务、活动资料。文件仅在当前页面使用。</p><label class="dy-upload">${icon('upload')} 添加图片 / 视频素材<input id="videoFiles" type="file" multiple accept=".jpg,.jpeg,.png,.webp,.mp4,.mov,.webm" onchange="addVideoFiles(this.files)"></label>${videoFlow.files.map((f,i)=>`<div class="dy-material"><span>${esc(f.name)}</span><small>${f.demo?'示例素材，非实际文件':'本地文件，未上传'}</small><button class="link" onclick="removeVideoFile(${i})" aria-label="移除素材 ${i+1}">移除</button></div>`).join('')}</div><div class="dy-card"><h3>员工会一起检查</h3><p>检查门店活动信息、危险操作、宣传表述、素材与人物授权、字幕和发布规格。真实内容识别与审查尚未接入。</p><label class="dy-check"><input id="vBriefAck" type="checkbox" onchange="document.getElementById('vGenerate').disabled=!this.checked">我已核对简报、负向要求和活动信息。</label><div class="dy-row actions"><button class="secondary" onclick="videoFlow.phase=0;render()">返回补充需求</button><button id="vGenerate" class="primary" disabled onclick="vConfirmBrief()">确认简报 · 进入生成</button></div></div>`;}
function vEditBrief(key,value){dyState.brief[key]=value;vChange();const ack=$('#vBriefAck');if(ack)ack.checked=false;const btn=$('#vGenerate');if(btn)btn.disabled=true;}
function loadVideoSample(){videoFlow.files=[{name:'门店外观.mp4',demo:true},{name:'员工服务.mp4',demo:true},{name:'会员活动资料.png',demo:true}];vChange();videoFlow.error='';render();}
function addVideoFiles(files){let invalid=[];if(videoFlow.files.some(x=>x.demo))videoFlow.files=[];for(const f of files){if(!/\.(jpe?g|png|webp|mp4|mov|webm)$/i.test(f.name)||!f.size){invalid.push(f.name);continue;}videoFlow.files.push({name:f.name,demo:false});}vChange();videoFlow.error=invalid.length?'未加入不支持或空文件：'+invalid.join('、'):'';render();}
function removeVideoFile(i){videoFlow.files.splice(i,1);vChange();render();}
function makeVideoPrompt(){const b=dyState.brief;return `原始需求：${b.request}\n目标：${b.goal}\n受众：${b.audience}\n主题：${b.theme}\n风格：${b.style}\n规格：${b.duration}秒 / ${b.ratio}\n口播：${b.voice}\n字幕：${b.subtitles}\n配乐：${b.music}\n结尾引导：${b.cta}\n必须保留：${b.must}\n不要出现：${b.avoid}\n活动资料与补充：${b.notes}\n参考素材：${videoFlow.files.map(x=>x.name).join('、')}\n生成前必须核实活动信息、行业安全及素材授权；不虚构价格、权益或平台审核结论。`;}
function vConfirmBrief(){const b=dyState.brief;if(!$('#vBriefAck')?.checked){toast('请确认当前简报');return;}if(!b.goal.trim()||!b.theme.trim()||!b.avoid.trim()){videoFlow.error='请补齐创作目标、主题，以及不要出现的内容。';render();return;}if(videoFlow.files.length<3){videoFlow.error='至少添加 3 个参考素材，也可使用示例素材体验。';render();return;}videoFlow.prompt=makeVideoPrompt();videoFlow.phase=2;videoFlow.error='';DY.log(dyState,'确认创作简报；等待视频生成服务，未生成真实视频');render();}
function vOutput(){const b=dyState.brief,a=dyState.asset;return `<div class="dy-card"><div class="dy-row"><h3>${a?'预览当前成片':'方案已确认，等待生成服务'}</h3><span class="dy-tag">${a?.kind==='local'?'本地视频':a?'交付示意':'待接入'}</span></div><p>目标规格：${esc(b.duration)} 秒 · ${esc(b.ratio)} · ${esc(b.style)}</p>${videoFlow.previewUrl?`<video class="dy-player" src="${esc(videoFlow.previewUrl)}" controls preload="metadata" onloadedmetadata="vVideoMetadata(this)" onerror="vVideoError(this)"></video><p id="vAssetMeta" class="dy-caption">${videoFlow.metadata?esc(videoFlow.metadata):'正在读取本地视频信息…'}</p>`:a?`<div class="dy-storyboard"><span>交付预览示意 · 非真实成片</span><div><strong>${esc(b.theme)}</strong><p>开场建立门店环境 → 服务细节 → 活动条件与结尾引导</p></div><small>未生成视频，不能播放或下载</small></div>`:`<div class="dy-empty">${icon('film')}<p>尚无视频文件。可体验示例交付，或导入已有成片预览。</p></div>`}<div class="dy-row actions"><button class="secondary" onclick="vDemoOutput()">体验示例交付</button><label class="dy-upload compact">导入本地成片<input type="file" id="vOutputFile" accept="video/mp4,video/webm,video/quicktime" onchange="vLoadOutput(this.files[0])"></label><button class="link" onclick="vDownloadBrief()">下载创作方案</button></div><details><summary>查看确认后的创作方案</summary><pre class="dy-brief-text">${esc(videoFlow.prompt)}</pre></details><label class="dy-check"><input id="vAssetAck" type="checkbox" ${a?.confirmed?'checked':''} ${!a?'disabled':''} onchange="vConfirmAsset(this.checked)">我已核对当前${a?.kind==='demo'?'交付示意':'成片'}、画面文字、活动条件和使用授权。</label><div class="dy-row actions"><button class="secondary" onclick="videoFlow.phase=1;render()">返回修改简报</button><button class="primary" ${!a?.confirmed?'disabled':''} onclick="vStartPublish()">选择发布账号与商品 →</button></div><p class="dy-caption">示例交付只能用于本地发布草案；本地导入的视频也不会被上传。更改简报或素材后需重新确认。</p></div>`;}
function vDemoOutput(){vClearMedia();dyState.asset={id:'demo-'+dyState.revision,kind:'demo',name:'交付预览示意',confirmed:false};DY.invalidate(dyState);render();}
function vLoadOutput(file){if(!file)return;if(!/\.(mp4|webm|mov)$/i.test(file.name)||file.size===0){toast('请选择有效的 MP4、WEBM 或 MOV 视频');return;}vClearMedia();dyState.asset=null;DY.invalidate(dyState);videoFlow.previewUrl=URL.createObjectURL(file);videoFlow.pendingOutput={name:file.name,id:'local-'+file.lastModified+'-'+file.size,kind:'local',confirmed:false};videoFlow.mediaContext={tenant:dyState.tenant,revision:dyState.revision,url:videoFlow.previewUrl};render();}
function vCurrentMedia(el){const c=videoFlow.mediaContext;return !!c&&c.tenant===dyState.tenant&&c.revision===dyState.revision&&(el.currentSrc||el.src)===c.url;}
function vVideoMetadata(el){if(!vCurrentMedia(el))return;if(!Number.isFinite(el.duration)||!el.videoWidth){vVideoError(el);return;}videoFlow.metadata=`实际文件：${el.videoWidth} × ${el.videoHeight} · ${el.duration.toFixed(1)} 秒`;if(videoFlow.pendingOutput){dyState.asset=videoFlow.pendingOutput;videoFlow.pendingOutput=null;render();}}
function vVideoError(el){if(el&&!vCurrentMedia(el))return;dyState.asset=null;DY.invalidate(dyState);videoFlow.error='无法读取视频，请换一个浏览器可播放的文件。';vClearMedia();render();}
function vConfirmAsset(checked){if(!dyState.asset)return;dyState.asset.confirmed=checked;DY.invalidate(dyState);render();}
function vStartPublish(){if(!dyState.asset?.confirmed){toast('请先确认当前成片');return;}videoFlow.phase=3;videoFlow.error='';if(!dyState.target.shop)dyState.target.shop=DY.shops(dyState)[0].id;render();}
function vSetTarget(key,value){dyState.target[key]=value;if(key==='shop'){dyState.target.product='';dyState.target.account='';}DY.invalidate(dyState);if(key==='title'){const ack=$('#vPublishAck');if(ack)ack.checked=false;const btn=$('#vSavePublish');if(btn)btn.disabled=true;const prev=$('#vPublishSnapshot');if(prev)prev.innerHTML='<p>标题已修改，请重新预览发布信息。</p>';}else render();}
function vPublish(){const t=dyState.target,shop=DY.shops(dyState).find(x=>x.id===t.shop),accounts=DY.accounts(dyState,t.shop),products=DY.products(dyState,t.shop),product=products.find(x=>x.id===t.product),jobs=dyState.jobs.filter(x=>x.tenant===dyState.tenant);return `<div class="dy-card"><div class="dy-row"><h3>把这条视频发到哪个账号？</h3><button class="link" onclick="navigate('authorize')">连接 / 调整授权 →</button></div><div class="dy-form-grid"><div class="field"><label for="vPublishShop">关联油站</label><select id="vPublishShop" onchange="vSetTarget('shop',this.value)">${dyOptions(DY.shops(dyState),t.shop,'选择门店')}</select></div><div class="field"><label for="vPublishAccount">已绑定且有发布授权的抖音号</label><select id="vPublishAccount" onchange="vSetTarget('account',this.value)">${dyOptions(accounts,t.account,'选择授权账号')}</select></div><div class="field wide"><label for="vPublishProduct">选品参考 · 不作为视频商品锚点</label><select id="vPublishProduct" onchange="vSetTarget('product',this.value)">${dyOptions(products,t.product,'可选：选择门店商品作创作参考')}</select></div><div class="field wide"><label for="vPublishTitle">发布标题</label><textarea id="vPublishTitle" maxlength="1000" oninput="vSetTarget('title',this.value)" placeholder="请输入最终发布标题">${esc(t.title)}</textarea></div></div><div class="dy-soft"><strong>发布方式：POI锚点方案（仍须能力获批）</strong><p>原生团购商品锚点：未确认支持，当前不可选。商品只作选品参考，读取商品不等于具备商品挂载权限。</p><p>POI：${esc(shop?.poi||'待选择')}<br>商品：${esc(product?product.name+' · '+product.price:'待选择')}<br>商品参考标识（不挂载）：${product?'待真实来客同步（当前仅示例商品标识 '+esc(product.link)+'）':'待选择授权商品'}</p></div>${!accounts.length?'<p class="dy-inline-error">请在授权中心完成当前门店的抖音发布授权与来客商品读取授权；未授权资源不会列出。</p>':''}<div class="dy-row actions"><button class="secondary" onclick="videoFlow.phase=2;render()">返回看成片</button><button class="primary" onclick="vPreviewPublish()">预览发布信息</button></div></div><div id="vPublishSnapshot">${dyState.preview?`<div class="dy-card"><div class="dy-row"><h3>最终发布确认</h3><span class="dy-tag">当前版本</span></div><dl class="dy-dl"><dt>目标账号</dt><dd>${esc(accounts.find(a=>a.id===t.account)?.name)}</dd><dt>成片</dt><dd>${esc(dyState.asset?.name)}</dd><dt>门店 / POI</dt><dd>${esc(shop?.name)} / ${esc(shop?.poi)}</dd><dt>选品参考</dt><dd>${esc(product?.name||'不使用选品参考')}</dd><dt>标题</dt><dd>${esc(t.title)}</dd></dl><label class="dy-check"><input id="vPublishAck" type="checkbox" ${dyState.ack?'checked':''} onchange="dyState.ack=this.checked;document.getElementById('vSavePublish').disabled=!this.checked">我确认当前内容、目标账号、POI及选品参考（不挂载），保存本地发布演示任务。</label><div class="dy-row actions"><button id="vSavePublish" class="primary" ${dyState.ack?'':'disabled'} onclick="vSavePublish()">确认 · 保存发布演示任务</button><button class="secondary" disabled>直接发布 · 待接口接入</button></div><p class="dy-caption">真实发布须video.create.bind获批及账号授权，POI需满足资质；当前不提供原生团购商品挂载。当前不会上传或发布作品，不将“保存草案”显示为“发布成功”。</p></div>`:''}</div>${jobs.length?`<div class="dy-card"><h3>本企业发布任务</h3>${jobs.map(j=>`<div class="dy-account"><div class="dy-row"><strong>${esc(j.id)}</strong><span class="dy-tag warn">${j.status}</span></div><p>${esc(j.target.title)} · ${esc(j.asset.name)}</p><small>已保存本地任务，未产生抖音作品 ID。</small></div>`).join('')}</div>`:''}`;}
function vPreviewPublish(){const error=DY.previewPublish(dyState);if(error){videoFlow.error=error;render();return;}videoFlow.error='';render();document.getElementById('vPublishSnapshot').scrollIntoView({behavior:'smooth',block:'start'});}
function vSavePublish(){const result=DY.savePublish(dyState);if(!result.ok){videoFlow.error=result.error;render();return;}render();toast(result.duplicate?'已存在同一版本的演示任务，未重复创建':'发布演示任务已保存；未执行真实发布');}
function vDownloadBrief(){const blob=new Blob([videoFlow.prompt+'\n\n本地交互演示，未生成或发布真实视频。'],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='抖音视频创作简报.txt';a.click();URL.revokeObjectURL(url);}
function renderVideoRight(){renderDouyinRight();}
